"use client";
import "./rams/styles.css";
import { useState, type ReactNode } from "react";
import { Input } from "./rams/components/motion-input";
function FieldExample({ children }: {
    children: ReactNode;
}) {
    return (<div style={{
            display: "grid",
            gridTemplateColumns: "minmax(0, 1fr)",
            gap: "var(--rams-detail-preview-field-stack-gap)",
            inlineSize: "100%",
            maxInlineSize: "min(100%, var(--rams-detail-preview-field-compact-measure))",
            marginInline: "auto",
            minInlineSize: 0,
            fontSize: "var(--type-control-size)",
            fontFamily: "inherit",
            color: "var(--rams-detail-foreground)",
        }}>
      {children}
    </div>);
}
function PlateSpecimen({ reference, marks = true, }: {
    reference: string;
    marks?: boolean;
}) {
    return (<svg viewBox="0 0 360 180" role="img" aria-label={`Plate ${reference}${marks ? " with crop marks" : " without crop marks"}`} style={{
            display: "block",
            width: "100%",
            height: "auto",
            color: "var(--rams-detail-foreground)",
            background: "var(--rams-detail-surface-muted)",
        }}>
      <rect x="32" y="32" width="296" height="116" fill="none" stroke="currentColor"/>
      <text x="180" y="103" textAnchor="middle" fontSize="var(--rams-detail-preview-plate-reference-type)" fill="currentColor">
        {reference}
      </text>
      {marks && (<g data-proof-marks aria-hidden="true" stroke="currentColor" strokeWidth="var(--rams-detail-preview-plate-crop-stroke)">
          <path d="M20 32h-8m20-12v-8M328 20v-8m12 20h8M20 148h-8m20 12v8m296-8v8m12-20h8"/>
        </g>)}
    </svg>);
}
export function InputDemo() {
    const [value, setValue] = useState("RS-08"), [touched, setTouched] = useState(false);
    const valid = /^[A-Z]{2}-[0-9]{2}$/.test(value);
    return (<FieldExample>
      <Input label="Plate reference" value={value} maxLength={5} onChange={(event) => setValue(event.target.value)} onBlur={() => setTouched(true)} description={`${5 - value.length} characters available`} error={touched && !valid
            ? "Use two uppercase letters, a hyphen and two digits."
            : undefined}/>
      <PlateSpecimen reference={valid ? value : "Unassigned"}/>
    </FieldExample>);
}
export default InputDemo;

