"use client";
import "./rams/styles.css";
import { useState, useRef, useLayoutEffect, type ReactNode } from "react";
import { EmptyState } from "./rams/components/motion-empty-state";
import { Button } from "./rams/components/button";
function PresentationExample({ children }: {
    children: ReactNode;
}) {
    return (<div style={{
            display: "grid",
            gap: "var(--rams-detail-preview-section-gap)",
            width: "100%",
            maxWidth: "var(--rams-detail-preview-measure)",
            minWidth: 0,
            marginInline: "auto",
            fontSize: "var(--type-control-size)",
            color: "var(--foreground,var(--rams-ink))",
        }}>
      {children}
    </div>);
}
function CoverArtwork() {
    return (<svg viewBox="0 0 280 180" role="img" aria-label="Patio 10 cover, a folded river study" style={{
            display: "block",
            width: "100%",
            height: "auto",
            background: "var(--muted,var(--rams-subtle))",
            color: "inherit",
        }}>
      <rect x="48" y="18" width="184" height="144" fill="none" stroke="currentColor"/>
      <path d="M70 122c22-70 44 20 66-50s44 20 66-30" fill="none" stroke="currentColor" strokeWidth="var(--rams-detail-preview-folded-cover-contour-stroke)"/>
      <text x="68" y="49" fill="currentColor" fontSize="var(--rams-detail-preview-folded-cover-label-size)">
        PATIO / 10
      </text>
    </svg>);
}
export function EmptyDemo() {
    const [created, setCreated] = useState(false), action = useRef<HTMLButtonElement>(null), previous = useRef<HTMLButtonElement | null>(null);
    useLayoutEffect(() => {
        const owner = previous.current;
        previous.current = null;
        if (owner &&
            !owner.isConnected &&
            (document.activeElement === document.body ||
                document.activeElement === owner))
            action.current?.focus();
    }, [created]);
    function toggle(owner: HTMLButtonElement) {
        previous.current = owner;
        setCreated((value) => !value);
    }
    return (<PresentationExample>
      {created ? (<>
          <CoverArtwork />
          <strong>Patio / 10</strong>
          <p>One cover in the rack.</p>
          <Button ref={action} type="button" variant="secondary" onClick={(event) => toggle(event.currentTarget)}>
            Remove cover
          </Button>
        </>) : (<EmptyState label="Cover rack" title="No covers in the rack" description="Add the river study to begin this edition." action={<Button ref={action} type="button" onClick={(event) => toggle(event.currentTarget)}>
              Add cover
            </Button>}/>)}
    </PresentationExample>);
}
export default EmptyDemo;

