};
const row: CSSProperties = {
    display: "flex",
    flexWrap: "wrap",
    justifyContent: "center",
    alignItems: "center",
    gap: "var(--rams-detail-space-2)",
    minWidth: 0,
};
function Scene({ id, title, children, }: {
    id: string;
    title: string;
    children: ReactNode;
}) {
