    return (<section aria-labelledby={heading} data-actions-scene={id} style={frame}>
      <header style={{ display: "grid", gap: "var(--rams-detail-space-1)" }}>
        <span style={{
            color: "var(--rams-detail-text-muted)",
            fontSize: "var(--type-caption-size)",
