        </span>
        <strong id={heading} style={{ fontWeight: "var(--type-title-weight)" }}>{title}</strong>
      </header>
      {children}
    </section>);
}
function Caption({ children }: {
    children: ReactNode;
}) {
    return (<p role="status" style={{
            margin: 0,
            color: "var(--rams-detail-text-muted)",
            fontSize: "var(--type-caption-size)",
            lineHeight: "var(--type-caption-leading)",
            overflowWrap: "anywhere",
        }}>
      {children}
    </p>);
}
/** Web Crypto hashes the edition name and drawing parameters; pending never waits for a demonstration timer. */
export function MotionProofActionDemo() {
    const [edition, setEdition] = useState("Córdoba / Tile study 08");
    const [proof, setProof] = useState<{
        edition: string;
        digest: string;
    } | null>(null);
    const [error, setError] = useState("");
    const id = useId();
    const alive = useRef(true);
    const generation = useRef(0);
    useLayoutEffect(() => {
        alive.current = true;
        return () => {
            alive.current = false;
            generation.current += 1;
        };
    }, []);
    return (<Scene id="proof" title="Tile study / proof fingerprint">
      <label htmlFor={id} style={{ display: "grid", gap: "var(--rams-detail-space-2)" }}>
        Edition name
        <Input id={id} value={edition} onChange={(event) => {
            generation.current += 1;
            setEdition(event.target.value);
            setProof(null);
            setError("");
        }}/>
      </label>
      <div style={row}>
        <ActionButton label="Check proof" pendingLabel="Fingerprinting" successLabel="Proof checked" onAction={async () => {
            const request = ++generation.current;
            const name = edition.trim();
            setError("");
            if (!name)
                throw new Error("Enter an edition name before checking the proof.");
            const bytes = new TextEncoder().encode(JSON.stringify({
                edition: name,
                artwork: "cordoba-tile-08",
                quarterTurns: [0, 90, 180, 270],
            }));
            const stale = () => !alive.current || request !== generation.current;
            const hash = await crypto.subtle
                .digest("SHA-256", bytes)
                .catch((reason) => {
                if (stale())
                    throw new DOMException("Edition changed", "AbortError");
                throw reason;
            });
            if (stale())
                throw new DOMException("Edition changed", "AbortError");
            const digest = Array.from(new Uint8Array(hash), (byte) => byte.toString(16).padStart(2, "0")).join("");
            setProof({ edition: name, digest });
        }} onActionError={(reason) => {
            if (!alive.current ||
                (reason instanceof DOMException && reason.name === "AbortError"))
                return;
            setError(reason instanceof Error
                ? reason.message
                : "Proof could not be checked. Try again.");
        }}/>
      </div>
      {error && (<p role="alert" style={{ margin: 0, color: "var(--rams-detail-danger)", overflowWrap: "anywhere" }}>
          {error}
        </p>)}
      <svg role="img" aria-label="Córdoba tile study: four interlocking quarter circles" viewBox="0 0 400 210" style={{
            display: "block",
            inlineSize: "100%",
            blockSize: "auto",
            maxInlineSize: "var(--rams-detail-proof-action-demo-artwork-inline-max)",
            maxBlockSize: "var(--rams-detail-proof-action-demo-artwork-block-max)",
            marginInline: "auto",
            border: "var(--rams-detail-primitive-border-width) solid var(--rams-detail-border)",
            borderRadius: "var(--radius-control)",
            background: "var(--rams-detail-background)",
            color: "var(--rams-detail-foreground)",
        }}>
        <g transform="translate(120 25)" fill="none" stroke="currentColor" strokeWidth="var(--rams-detail-preview-fingerprint-stroke)">
          {[0, 1, 2, 3].map((index) => (<g key={index} transform={`rotate(${index * 90} 80 80)`}>
              <path d="M0 0h80v80H0zM0 80A80 80 0 0 1 80 0M0 60A60 60 0 0 1 60 0M0 40A40 40 0 0 1 40 0"/>
            </g>))}
        </g>
      </svg>
      <Caption>
        {proof ? (<>
            {proof.edition}
            <br />
            SHA-256{" "}
            <code style={{ fontFamily: "var(--type-code-family)", overflowWrap: "anywhere" }}>{proof.digest}</code>
          </>) : ("Tile study 08 · four quarter turns")}
      </Caption>
    </Scene>);
}
export default MotionProofActionDemo;

