                doneLabel: "Rotated",
                icon: <RotateCw />,
                onSelect: () => setTurns((value) => (value + 1) % 4),
            },
            {
                id: "mirror",
                label: "Mirror",
                doneLabel: "Mirrored",
                icon: <FlipHorizontal2 />,
                onSelect: () => setMirrored((value) => !value),
            },
            {
                id: "negative",
                label: "Invert",
                doneLabel: "Inverted",
                icon: <SunMoon />,
                onSelect: () => setNegative((value) => !value),
            },
            {
                id: "reset",
                label: "Reset",
                icon: <RotateCcw />,
                disabled: pristine,
                onSelect: () => {
                    setTurns(0);
                    setMirrored(false);
                    setNegative(false);
                },
            },
        ]}/>
      </div>
      <svg role="img" aria-label={`Block-print matrix: ${turns * 90} degrees, ${mirrored ? "mirrored" : "unmirrored"}, ${negative ? "negative" : "positive"}`} viewBox="0 0 360 230" style={proofArtwork}>
        <g transform={`translate(180 112) rotate(${turns * 90}) scale(${mirrored ? -1 : 1} 1)`}>
          <rect x="-80" y="-80" width="160" height="160" fill={negative ? "currentColor" : "none"} stroke="currentColor"/>
          <g fill={negative ? "var(--rams-detail-background)" : "currentColor"}>
            <path d="M-60-60h40V60h-40zM0-60h60v40H0zM0 0h40v60H0z"/>
            <circle cx="60" cy="60" r="20"/>
          </g>
        </g>
        <text x="180" y="215" textAnchor="middle" fill="currentColor" fontFamily="inherit" fontSize="var(--rams-detail-preview-block-print-caption-size)">
          MATRIX 12 / LA PLATA
        </text>
      </svg>
      <Caption>
        {turns * 90}° · {mirrored ? "mirrored" : "unmirrored"} ·{" "}
        {negative ? "negative" : "positive"} plate
      </Caption>
    </Scene>);
}
export default MotionBlockPrintToolsDemo;

