"use client";
import "./rams/styles.css";
import { useId, useRef, useState, type CSSProperties, type ReactNode, type Ref } from "react";
import { collectionPresentation } from "./rams/components/collection-presentation";
import { Button } from "./rams/components/button";
import { Input } from "./rams/components/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "./rams/components/select";
import { JsonViewer } from "./rams/components/motion-json-viewer";
const ink = "var(--foreground, var(--rams-ink, var(--rams-detail-native-content-ink-fallback)))";
const muted = "var(--muted-foreground, var(--rams-muted, var(--rams-detail-native-muted-ink-fallback)))";
const stack: CSSProperties = {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr)",
    minWidth: 0,
    gap: "var(--rams-detail-space-4, var(--rams-detail-preview-scene-gap))",
};
const caption: CSSProperties = {
