    overflowWrap: "anywhere",
};
function Study({ id, place, title, children, }: {
    id: string;
    place: string;
    title: string;
    children: ReactNode;
}) {
    const heading = useId();
    return (<section data-motion-data-scene={id} aria-labelledby={heading} style={{
            ...stack,
            width: "100%",
            color: ink,
            fontSize: "var(--type-body-size, var(--rams-detail-native-body-size-fallback))",
            lineHeight: "var(--type-body-leading, var(--rams-detail-native-body-leading-fallback))",
            overflowWrap: "anywhere",
        }}>
      <header style={{ ...stack, gap: "var(--rams-detail-preview-print-study-copy-gap)" }}>
        <span style={caption}>{place} / print room</span>
        <strong id={heading} style={{ fontSize: "var(--type-body-size, var(--rams-detail-native-body-size-fallback))", fontWeight: "var(--rams-detail-label-weight)" }}>
          {title}
        </strong>
      </header>
      {children}
    </section>);
}
function VariableSelect({ label, value, options, onValueChange, triggerRef, }: {
    label: string;
    value: string;
    options: readonly {
        value: string;
        label: string;
    }[];
    onValueChange: (value: string) => void;
    triggerRef?: Ref<HTMLButtonElement>;
}) {
    const id = useId();
    return (<div style={{ ...stack, gap: "var(--rams-detail-preview-control-stack-gap)" }}>
      <label htmlFor={id} style={{ fontSize: "var(--type-control-size, var(--rams-detail-native-control-size-fallback))" }}>
        {label}
      </label>
      <Select value={value} onValueChange={onValueChange}>
        <SelectTrigger ref={triggerRef} id={id} style={{ width: "100%", minWidth: 0 }}>
          <SelectValue>
            {options.find((option) => option.value === value)?.label}
          </SelectValue>
        </SelectTrigger>
        <SelectContent>
          {options.map((option) => (<SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>))}
        </SelectContent>
      </Select>
    </div>);
}
const formats = [
    { value: "folio", label: "Folio", perSheet: 2, inkPasses: 2 },
    { value: "cards", label: "Cards", perSheet: 4, inkPasses: 1 },
];
const runSizes = [
    { value: "24", label: "24" },
    { value: "48", label: "48" },
    { value: "72", label: "72" },
];
const originalTitle = "Rain atlas";
function makePrintTicket(title: string, format: (typeof formats)[number], copies: number) {
    const count = Math.ceil(copies / format.perSheet);
    return {
        title,
        city: "Tucumán",
        copies,
        layout: {
            format: format.value,
            perSheet: format.perSheet,
            inkPasses: format.inkPasses,
        },
        totals: { sheets: count, impressions: count * format.inkPasses },
        sheets: Array.from({ length: count }, (_, index) => ({
            sheet: index + 1,
            copies: Math.min(format.perSheet, copies - index * format.perSheet),
        })),
    };
}
export function MotionPrintTicketJsonDemo() {
    const titleId = useId();
    const searchId = useId();
    const [title, setTitle] = useState(originalTitle);
    const [formatName, setFormatName] = useState("folio");
    const [copies, setCopies] = useState("24");
    const [query, setQuery] = useState("");
    const searchControl = useRef<HTMLInputElement>(null);
    const [selectedPath, setSelectedPath] = useState("ticket");
    const selectedFormat = formats.find((format) => format.value === formatName)!;
    const ticket = makePrintTicket(title, selectedFormat, Number(copies));
    return (<Study id="print-ticket" place="Tucumán" title="An edition in plain data">
      <label htmlFor={titleId} style={{
            ...stack,
            gap: "var(--rams-detail-preview-control-stack-gap)",
            fontSize: "var(--type-control-size, var(--rams-detail-native-control-size-fallback))",
        }}>
        Edition title
        <Input id={titleId} value={title} onChange={(event) => setTitle(event.target.value)}/>
      </label>
      <VariableSelect label="Format" value={formatName} onValueChange={setFormatName} options={formats}/>
      <VariableSelect label="Copies" value={copies} onValueChange={setCopies} options={runSizes}/>
      <output style={{ ...stack, ...caption, gap: "var(--rams-detail-preview-print-study-copy-gap)" }}>
        <span>
          {ticket.copies} copies · {ticket.layout.perSheet} per sheet.
        </span>
        <span>
          {ticket.totals.sheets} sheets × {ticket.layout.inkPasses} ink{" "}
          {ticket.layout.inkPasses === 1 ? "pass" : "passes"} ={" "}
          {ticket.totals.impressions} impressions.
        </span>
      </output>
      <label htmlFor={searchId} style={{
            ...stack,
            gap: "var(--rams-detail-preview-control-stack-gap)",
            fontSize: "var(--type-control-size, var(--rams-detail-native-control-size-fallback))",
        }}>
        Find in ticket
        <Input id={searchId} ref={searchControl} type="search" value={query} onChange={(event) => setQuery(event.target.value)}/>
      </label>
      <Button type="button" variant="outline" disabled={!query} onClick={(event) => {
            if (event.currentTarget === document.activeElement)
                searchControl.current?.focus({ preventScroll: true });
            setQuery("");
        }}>
        Clear search
      </Button>
      <JsonViewer data={ticket} rootName="ticket" label="Print ticket" pageSize={collectionPresentation.printTicketPageSize} query={query} onQueryChange={setQuery} searchable={false} copyable={false} showPath={false} maxHeight="var(--rams-detail-preview-json-ticket-tree-max-block)" onSelect={({ path }) => setSelectedPath(path)}/>
      <output style={caption}>
        Selected path:{" "}
        <code style={{ color: ink, overflowWrap: "anywhere" }}>
          {selectedPath}
        </code>
      </output>
    </Study>);
}
export default MotionPrintTicketJsonDemo;

