        <rect x="1" y="1" width="238" height="328" fill="none" stroke="currentColor" strokeWidth="var(--rams-detail-preview-trim-sheet-frame-stroke)"/>
        {selected &&
            plan &&
            Array.from({ length: plan.perSheet }, (_, index) => {
                const x = (240 - plan.columns * selected.width) / 2 +
                    (index % plan.columns) * selected.width;
                const y = (330 - plan.rows * selected.height) / 2 +
                    Math.floor(index / plan.columns) * selected.height;
                return (<g key={index} data-imposed-copy={index + 1} transform={`translate(${x} ${y})`}>
                <rect width={selected.width} height={selected.height} fill="currentColor" fillOpacity="var(--rams-detail-preview-trim-copy-fill-opacity)" stroke="currentColor" strokeWidth="var(--rams-detail-preview-trim-copy-edge-stroke)"/>
                <path d={`M${selected.width * 0.1} ${selected.height * 0.72}Q${selected.width * 0.32} ${selected.height * 0.2} ${selected.width * 0.54} ${selected.height * 0.55}T${selected.width * 0.9} ${selected.height * 0.4}`} fill="none" stroke="currentColor" strokeWidth="var(--rams-detail-preview-trim-copy-illustration-stroke)"/>
                <path d={`M${selected.width * 0.14} ${selected.height * 0.2}h${selected.width * 0.35}M${selected.width * 0.14} ${selected.height * 0.26}h${selected.width * 0.2}`} stroke="currentColor" strokeWidth="var(--rams-detail-preview-trim-copy-text-stroke)"/>
              </g>);
            })}
      </svg>
      <output style={{ ...layout, ...note, lineHeight: "var(--rams-detail-preview-print-scene-leading)", gap: "var(--rams-detail-preview-trim-result-gap)" }}>
        {selected && plan ? (<>
            <span>
              {selected.label}: {selected.width} × {selected.height} mm.
            </span>
            <span>
              72 copies · {plan.perSheet} per sheet · {plan.sheets} sheets.
            </span>
            <span>
              {plan.spare
                ? `${plan.spare} spare positions on the last sheet.`
                : "No spare positions."}
            </span>
          </>) : (<span>Choose a trim to build the sheet.</span>)}
        <span>Fixed orientation · no gutters.</span>
      </output>
    </section>);
}
export default MotionTrimComboboxDemo;

