"use client";
import "./rams/styles.css";
import { printPreviewGeometry } from "./rams/components/print-preview-geometry";
import { useState, type CSSProperties } from "react";
import { Pagination } from "./rams/components/motion-pagination";
const ink = "var(--foreground, var(--rams-ink))";
const muted = "var(--muted-foreground, var(--rams-muted))";
const layout: CSSProperties = {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr)",
    width: "100%",
    minWidth: 0,
    gap: "var(--rams-detail-space-4)",
    color: ink,
    fontSize: "var(--type-body-size)",
    lineHeight: "var(--type-body-leading)",
    overflowWrap: "anywhere",
};
const note: CSSProperties = {
    margin: 0,
    color: muted,
    fontSize: "var(--type-caption-size)",
    lineHeight: "var(--type-body-leading)",
    overflowWrap: "anywhere",
};
const list: CSSProperties = {
    ...layout,
    listStyle: "none",
    margin: 0,
    padding: 0,
};
type ProofEdition = {
    code: string;
    edition: string;
    plates: [
        string,
        string
    ][];
};
const proofEditions: ProofEdition[] = [
    {
        code: "RL",
        edition: "River ledger",
        plates: [
            ["Bank", "Drypoint"],
            ["Reed", "Stencil"],
            ["Wake", "Relief"],
            ["Silt", "Line print"],
        ],
    },
    {
        code: "TR",
        edition: "Tile rhythm",
        plates: [
            ["Corner", "Relief"],
            ["Joint", "Drypoint"],
            ["Glaze", "Stencil"],
            ["Edge", "Line print"],
        ],
    },
    {
        code: "MT",
        edition: "Market type",
        plates: [
            ["Awning", "Stencil"],
            ["Crate", "Relief"],
            ["Label", "Line print"],
            ["Stall", "Drypoint"],
        ],
    },
    {
        code: "RS",
        edition: "Rail study",
        plates: [
            ["Sleeper", "Relief"],
            ["Switch", "Line print"],
            ["Signal", "Stencil"],
            ["Track", "Drypoint"],
        ],
    },
    {
        code: "SH",
        edition: "Roof shadows",
        plates: [
            ["Ridge", "Drypoint"],
            ["Eave", "Stencil"],
            ["Vent", "Line print"],
            ["Pitch", "Relief"],
        ],
    },
    {
        code: "GC",
        edition: "Garden cuts",
        plates: [
            ["Seed", "Stencil"],
            ["Leaf", "Relief"],
            ["Stem", "Drypoint"],
            ["Petal", "Line print"],
        ],
    },
    {
        code: "CY",
        edition: "Courtyard",
        plates: [
            ["Arch", "Relief"],
            ["Paving", "Line print"],
            ["Well", "Drypoint"],
            ["Gate", "Stencil"],
        ],
    },
];
const proofs = proofEditions.flatMap((edition) => edition.plates.map(([title, process], index) => ({
    id: `${edition.code}-${String(index + 1).padStart(2, "0")}`,
    title,
    edition: edition.edition,
    process,
})));
function proofWindow(page: number) {
    const { pageSize } = printPreviewGeometry.proofIndex;
    const start = (page - 1) * pageSize;
    return {
        records: proofs.slice(start, start + pageSize),
        first: start + 1,
        last: Math.min(start + pageSize, proofs.length),
        total: proofs.length,
        pageCount: Math.ceil(proofs.length / pageSize),
    };
}
export function MotionProofIndexPaginationDemo() {
    const [page, setPage] = useState(1);
    const shown = proofWindow(page);
    return (<section style={layout} aria-label="Córdoba proof index" data-navigation-scene="proof-index">
      <header>
        <p style={note}>Córdoba / proof index</p>
        <strong>28 plates from seven edition studies</strong>
      </header>
      <ul style={list}>
        {shown.records.map((record) => (<li key={record.id} data-proof-id={record.id} style={{
                display: "grid",
                gridTemplateColumns: "minmax(0, 1fr)",
                minWidth: 0,
                gap: "var(--rams-detail-preview-print-study-copy-gap)",
            }}>
            <strong style={{ fontWeight: "var(--type-action-weight)" }}>
              {record.id} · {record.title}
            </strong>
            <span style={note}>{record.edition}</span>
            <span style={note}>{record.process}</span>
          </li>))}
      </ul>
      <output style={note}>
        Showing proofs {shown.first}–{shown.last} of {shown.total}.
      </output>
      <Pagination page={page} pageCount={shown.pageCount} onPageChange={setPage} label="Proof index pages"/>
    </section>);
}
export default MotionProofIndexPaginationDemo;

