"use client";
import "./rams/styles.css";
import { useId, useState, type CSSProperties } from "react";
import { Button } from "./rams/components/button";
import { Input } from "./rams/components/input";
import { Dialog, DialogClose, DialogContent, DialogTrigger } from "./rams/components/motion-dialog";
const ink = "var(--foreground, var(--rams-ink, var(--rams-detail-native-content-ink-fallback)))";
const muted = "var(--muted-foreground, var(--rams-muted, var(--rams-detail-native-muted-ink-fallback)))";
const layout: CSSProperties = {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr)",
    minWidth: 0,
    width: "100%",
    gap: "var(--rams-detail-space-4, var(--rams-detail-preview-scene-gap))",
    color: ink,
    fontSize: "var(--type-body-size, var(--rams-detail-native-body-size-fallback))",
    lineHeight: "var(--rams-detail-preview-print-scene-leading)",
    overflowWrap: "anywhere",
};
const note: CSSProperties = {
    margin: 0,
    color: muted,
    fontSize: "var(--type-caption-size, var(--rams-detail-preview-print-scene-caption-size-fallback))",
    lineHeight: "var(--rams-detail-preview-print-scene-leading)",
    overflowWrap: "anywhere",
};
const field: CSSProperties = {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr)",
    minWidth: 0,
    gap: "var(--rams-detail-preview-control-stack-gap)",
};
export function MotionPrintTitleDialogDemo() {
    const [title, setTitle] = useState("River margin");
    const [draft, setDraft] = useState(title);
    const [open, setOpen] = useState(false);
    const [error, setError] = useState("");
    const inputId = useId();
    const errorId = useId();
    const changeOpen = (next: boolean) => {
        setDraft(title);
        setError("");
        setOpen(next);
    };
    return (<section style={layout} aria-label="Rosario print title" data-overlay-scene="print-title">
      <header>
        <p style={note}>Rosario / edition 08</p>
        <h3 style={{
            margin: 0,
            fontSize: "var(--type-body-size)",
            fontWeight: "var(--rams-detail-docs-subheading-weight)",
        }}>
          {title}
        </h3>
      </header>
      <p style={note}>Relief proof · 140 × 200 mm.</p>
      <Dialog open={open} onOpenChange={changeOpen}>
        <DialogTrigger asChild>
          <Button type="button" variant="outline">
            Edit print title
          </Button>
        </DialogTrigger>
        <DialogContent title="Edit print title" description="The saved title appears on the proof.">
          <form noValidate style={layout} onSubmit={(event) => {
            event.preventDefault();
            const next = draft.trim();
            if (!next) {
                setError("Enter a print title.");
                return;
            }
            setTitle(next);
            setDraft(next);
            setError("");
            setOpen(false);
        }}>
            <label htmlFor={inputId} style={field}>
              Print title
              <Input id={inputId} value={draft} maxLength={48} required aria-invalid={error ? true : undefined} aria-describedby={error ? errorId : undefined} onChange={(event) => {
            setDraft(event.target.value);
            setError("");
        }}/>
            </label>
            {error && (<p id={errorId} role="alert" style={{
                ...note,
                color: "var(--rams-detail-danger)",
            }}>
                {error}
              </p>)}
            <div style={field}>
              <DialogClose asChild>
                <Button type="button" variant="outline">
                  Cancel
                </Button>
              </DialogClose>
              <Button type="submit">Save title</Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </section>);
}
export default MotionPrintTitleDialogDemo;

