"use client";
import "./rams/styles.css";
import { useId, useState, type CSSProperties, type ReactNode } from "react";
import { TreeView, type TreeNode } from "./rams/components/motion-tree-view";
const ink = "var(--rams-detail-foreground)";
const paper = "var(--rams-detail-background)";
const muted = "var(--muted-foreground, var(--rams-detail-text-secondary))";
const stack: CSSProperties = {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr)",
    minWidth: 0,
    gap: "var(--rams-detail-space-3)",
};
const note: CSSProperties = {
    margin: 0,
    color: muted,
    fontSize: "var(--type-caption-size)",
    lineHeight: "var(--type-body-leading)",
    overflowWrap: "anywhere",
};
const artwork: CSSProperties = {
    display: "block",
    width: "100%",
    height: "auto",
    minWidth: 0,
    background: paper,
    color: ink,
};
function PrintStudy({ name, place, title, children, }: {
    name: string;
    place: string;
    title: string;
    children: ReactNode;
}) {
    const heading = useId();
    return (<section data-print-organization={name} aria-labelledby={heading} style={{
            ...stack,
            color: ink,
            fontSize: "var(--type-body-size)",
            lineHeight: "var(--type-body-leading)",
            overflowWrap: "anywhere",
        }}>
      <header>
        <p style={note}>{place}</p>
        <strong id={heading}>{title}</strong>
      </header>
      {children}
    </section>);
}
type PrintPlate = {
    id: string;
    title: string;
    place: string;
    process: string;
    paper: string;
    sheets: number;
    line: string;
};
const printPlates: PrintPlate[] = [
    {
        id: "RQ-01",
        title: "Landing",
        place: "Rosario",
        process: "Relief",
        paper: "Cotton",
        sheets: 48,
        line: "M8 56H92M8 44H72V18H92M8 32H52V8",
    },
    {
        id: "RQ-02",
        title: "Tide stair",
        place: "Rosario",
        process: "Drypoint",
        paper: "Rag",
        sheets: 24,
        line: "M8 56H28V44H48V32H68V20H92M8 16Q48 36 92 8",
    },
    {
        id: "CS-01",
        title: "Tile shade",
        place: "Córdoba",
        process: "Relief",
        paper: "Rag",
        sheets: 36,
        line: "M12 8V56H88V8ZM12 32H88M36 8V56M64 8V56M12 8L88 56",
    },
    {
        id: "CS-02",
        title: "Arch seam",
        place: "Córdoba",
        process: "Stencil",
        paper: "Cotton",
        sheets: 60,
        line: "M16 56V32A34 24 0 0 1 84 32V56M32 56V32A18 12 0 0 1 68 32V56M8 56H92",
    },
    {
        id: "MC-01",
        title: "Canal turn",
        place: "Mendoza",
        process: "Stencil",
        paper: "Rag",
        sheets: 30,
        line: "M8 16H52Q84 16 84 48V56M8 32H44Q68 32 68 52V56M8 48H36",
    },
    {
        id: "MC-02",
        title: "Vine grid",
        place: "Mendoza",
        process: "Relief",
        paper: "Cotton",
        sheets: 42,
        line: "M16 8V56M40 8V56M64 8V56M88 8V56M8 20H92M8 44H92M16 56L88 8",
    },
];
const places = ["Rosario", "Córdoba", "Mendoza"];
const plateTree: TreeNode[] = places.map((place, index) => ({
    id: `cabinet-${index}`,
    label: place,
    children: printPlates
        .filter((plate) => plate.place === place)
        .map((plate) => ({ id: plate.id, label: plate.title })),
}));
const sheetTotal = (plates: PrintPlate[]) => plates.reduce((total, plate) => total + plate.sheets, 0);
function PlateDirectory({ plates }: {
    plates: PrintPlate[];
}) {
    return (<ul style={{ ...stack, margin: 0, paddingInlineStart: "var(--rams-detail-preview-unordered-list-inset)", gap: "var(--rams-detail-preview-list-gap)" }}>
      {plates.map((plate) => (<li key={plate.id}>
          <strong>
            {plate.id} · {plate.title}
          </strong>
          <p style={note}>
            {plate.place} · {plate.process} · {plate.paper} · {plate.sheets}{" "}
            sheets
          </p>
        </li>))}
    </ul>);
}
export function MotionPlateCabinetTreeDemo() {
    const [selected, setSelected] = useState<TreeNode | null>(null);
    const branch = plateTree.find((node) => node.id === selected?.id);
    const shown = !selected
        ? printPlates
        : branch
            ? printPlates.filter((plate) => branch.children?.some((child) => child.id === plate.id))
            : printPlates.filter((plate) => plate.id === selected.id);
    const title = selected?.label ?? "Cabinet overview";
    const rows = Math.ceil(shown.length / 2);
    return (<PrintStudy name="cabinet-tree" place="Three-city plate cabinet" title="Find a plate">
      <TreeView nodes={plateTree} defaultExpandedIds={["cabinet-0"]} onSelect={setSelected} aria-label="Print plate cabinet"/>
      <div style={stack}>
        <strong>{title}</strong>
        <p role="status" style={note}>
          {shown.length} {shown.length === 1 ? "plate" : "plates"} ·{" "}
          {sheetTotal(shown)} reference sheets
        </p>
        <svg viewBox={`0 0 240 ${rows * 80}`} role="img" aria-label={`${title}: ${shown.map((plate) => plate.title).join(", ")}`} style={artwork}>
          {shown.map((plate, index) => (<g key={plate.id} transform={`translate(${(index % 2) * 120 + 10} ${Math.floor(index / 2) * 80 + 8})`}>
              <rect width="100" height="64" fill="none" stroke="currentColor" opacity="var(--rams-detail-preview-plate-frame-opacity)"/>
              <path d={plate.line} fill="none" stroke="currentColor" strokeWidth="var(--rams-detail-preview-plate-line-stroke)" strokeLinejoin="round"/>
            </g>))}
        </svg>
        <PlateDirectory plates={shown}/>
      </div>
    </PrintStudy>);
}
export default MotionPlateCabinetTreeDemo;

