"use client";
import "./rams/styles.css";
import { useId, useState, type CSSProperties, type ReactNode } from "react";
import { Button } from "./rams/components/button";
import { ReorderableList, type ReorderableItem } from "./rams/components/motion-reorderable-list";
const ink = "var(--rams-detail-foreground)";
const paper = "var(--rams-detail-background)";
const muted = "var(--muted-foreground, var(--rams-detail-text-secondary))";
const stack: CSSProperties = {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr)",
    minWidth: 0,
    gap: "var(--rams-detail-space-3)",
};
const note: CSSProperties = {
    margin: 0,
    color: muted,
    fontSize: "var(--type-caption-size)",
    lineHeight: "var(--type-body-leading)",
    overflowWrap: "anywhere",
};
const artwork: CSSProperties = {
    display: "block",
    width: "100%",
    height: "auto",
    minWidth: 0,
    background: paper,
    color: ink,
};
function PrintStudy({ name, place, title, children, }: {
    name: string;
    place: string;
    title: string;
    children: ReactNode;
}) {
    const heading = useId();
    return (<section data-print-organization={name} aria-labelledby={heading} style={{
            ...stack,
            color: ink,
            fontSize: "var(--type-body-size)",
            lineHeight: "var(--type-body-leading)",
            overflowWrap: "anywhere",
        }}>
      <header>
        <p style={note}>{place}</p>
        <strong id={heading}>{title}</strong>
      </header>
      {children}
    </section>);
}
const bookletSections: ReorderableItem[] = [
    { id: "quay", title: "Quay fold", detail: "Rosario · 4 pages" },
    { id: "steps", title: "Stone steps", detail: "Córdoba · 8 pages" },
    { id: "canal", title: "Canal ledger", detail: "Mendoza · 4 pages" },
    { id: "vine", title: "Vine screen", detail: "Mendoza · 8 pages" },
];
const sectionPages: Record<string, number> = {
    quay: 4,
    steps: 8,
    canal: 4,
    vine: 8,
};
export function MotionBookletSequenceDemo() {
    const [sections, setSections] = useState<ReorderableItem[]>(bookletSections);
    let nextPage = 1;
    const index = sections.map((section) => {
        const first = nextPage;
        nextPage += sectionPages[section.id]!;
        return { ...section, first, last: nextPage - 1 };
    });
    const original = sections.every((section, position) => section.id === bookletSections[position]?.id);
    return (<PrintStudy name="booklet-sequence" place="Three-city walking booklet" title="Set the reading sequence">
      <p style={note}>
        Drag a section handle, or focus it and use Arrow Up and Arrow Down. Page
        ranges follow the reading order.
      </p>
      <ReorderableList items={sections} onReorder={setSections} label="Booklet reading sequence"/>
      <Button type="button" variant="outline" disabled={original} onClick={() => setSections(bookletSections)}>
        Reset order
      </Button>
      <p role="status" style={note}>
        Opening section: {sections[0]!.title} · {nextPage - 1} pages
      </p>
      <svg viewBox="0 0 240 48" role="img" aria-label={`Booklet page blocks in order: ${index.map((section) => section.title).join(", ")}`} style={artwork}>
        {index.map((section, position) => (<rect key={section.id} x={(section.first - 1) * 10 + 1} y="8" width={(section.last - section.first + 1) * 10 - 2} height="32" fill="currentColor" opacity={position % 2 ? "var(--rams-detail-preview-page-block-secondary-opacity)" : "var(--rams-detail-preview-page-block-primary-opacity)"}/>))}
      </svg>
      <ol style={{
            ...stack,
            margin: 0,
            paddingInlineStart: "var(--rams-detail-preview-ordered-list-inset)",
            gap: "var(--rams-detail-preview-list-gap)",
        }}>
        {index.map((section) => (<li key={section.id}>
            <strong>{section.title}</strong>
            <p style={note}>
              Pages {section.first}–{section.last}
            </p>
          </li>))}
      </ol>
    </PrintStudy>);
}
export default MotionBookletSequenceDemo;

