import { Button } from "./rams/components/button";
import { Stepper, type StepperStep } from "./rams/components/motion-stepper";
const sceneStyle: React.CSSProperties = {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr)",
    width: "100%",
