    <SwipeActions label="Proof sheets" emptyState={<p style={copyStyle}>All three proofs are archived.</p>}>
      {rows.map(row => <SwipeActionsRow key={row.id} label={row.title} leading={[{ label: checked.includes(row.id) ? "Mark unchecked" : "Mark checked", icon: <Check aria-hidden="true"/>, tone: "accent", keepRow: true, onSelect: () => setChecked(current => current.includes(row.id) ? current.filter(id => id !== row.id) : [...current, row.id]) }]} trailing={[{ label: "Archive proof", icon: <Archive aria-hidden="true"/>, onSelect: () => { setRows(current => current.filter(item => item.id !== row.id)); setArchived(current => [...current, row.title]); } }]}>
