          <span style={{ fontSize: "var(--type-caption-size, var(--rams-detail-preview-print-scene-caption-size-fallback))" }}>{row.sheet} · {checked.includes(row.id) ? "Checked" : "Unchecked"}</span>
        </div>
      </SwipeActionsRow>)}
