    <p role="status" style={copyStyle}>{archived.length ? `Archived proofs: ${archived.join("; ")}.` : "No proofs archived."}</p>
    <Button variant="outline" onClick={() => { setRows(proofRows); setChecked([]); setArchived([]); }}>Restore proofs</Button>
  </section>;
}
